@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#f4f3ec;--muted:#a9b5b7;--mint:#b6dfc9;--gold:#e9c889;--panel:#172733;--line:rgba(222,239,231,.12);font-family:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#101a27;color:var(--ink);min-height:100vh;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer}.game-shell{height:100vh;min-height:540px;display:grid;grid-template-rows:68px 1fr 30px;background:#101a27}.topbar{z-index:5;display:flex;align-items:center;justify-content:space-between;padding:0 34px;border-bottom:1px solid rgba(255,255,255,.07);background:#111d29}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none;font:800 13px Manrope,sans-serif;letter-spacing:1.55px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(228,202,151,.55);border-radius:11px;color:var(--gold);font-size:19px}.brand small{display:block;color:#90a0a5;font:600 8px 'DM Sans',sans-serif;letter-spacing:2.1px;margin-top:3px}.top-center{display:flex;align-items:center;gap:12px;color:#aab8b8;font-size:9px;font-weight:700;letter-spacing:1.6px}.season-dot{width:7px;height:7px;border-radius:50%;background:#c9e6d3;box-shadow:0 0 10px #b6dfc9}.top-divider{height:13px;width:1px;background:#526067;margin:0 3px}.top-actions{display:flex;gap:9px;align-items:center}.icon-btn,.avatar-btn{height:33px;width:34px;border-radius:10px;border:1px solid var(--line);background:#192833;color:#c5d0ca;font-size:16px}.avatar-btn{border:0;background:#d8b783;color:#3b3226;font-weight:800;border-radius:50%;width:32px;height:32px}.game-area{position:relative;overflow:hidden;background:#5d95a0}.game-area canvas{position:absolute;width:100%;height:100%;inset:0;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,27,35,.07),transparent 30%,transparent 72%,rgba(15,27,36,.22));}.glass{background:rgba(19,34,43,.78);border:1px solid rgba(238,244,227,.17);backdrop-filter:blur(15px);box-shadow:0 12px 40px rgba(11,26,34,.16)}.quest-card{position:absolute;top:26px;left:30px;width:310px;padding:17px 19px 15px;border-radius:14px;z-index:2}.quest-kicker{display:flex;align-items:center;font-size:8px;letter-spacing:1.5px;font-weight:700;color:#c7d7cc}.quest-icon{font-size:15px;color:var(--gold);margin-right:8px}.quest-step{margin-left:auto;color:#8da19f;font-size:8px}.quest-card h1{font:700 19px Manrope,sans-serif;letter-spacing:-.55px;margin:12px 0 6px}.quest-card p{color:#afbfbb;font-size:11px;line-height:1.55;margin:0 0 15px;max-width:260px}.quest-progress{height:3px;background:#36474b;border-radius:9px;overflow:hidden}.quest-progress span{display:block;width:8%;height:100%;background:#c6e1ca;border-radius:9px;transition:width .35s}.quest-foot{display:flex;justify-content:space-between;align-items:center;margin-top:9px;font-size:9px;color:#8fa4a0}.quest-foot span:last-child{color:#e5c88c;font-weight:700}.weather-pill{position:absolute;top:27px;right:30px;height:35px;padding:0 13px;display:flex;align-items:center;gap:8px;border-radius:20px;font-size:8px;font-weight:700;letter-spacing:1.3px;color:#d4e0d9}.weather-icon{font-size:14px;color:#f4d28c}.weather-sep{color:#7d9291;font-size:14px}.resource-tray{position:absolute;top:77px;right:30px;display:flex;align-items:center;padding:9px 13px;border-radius:12px;gap:13px}.resource-tray>i{height:23px;width:1px;background:rgba(228,240,229,.13)}.resource{display:flex;align-items:center;gap:8px;min-width:50px}.resource-icon{font-size:15px}.wood-icon{color:#d7ad74}.stone-icon{color:#b4c5c2}.crystal-icon{color:#d0bbf0}.resource b{font:700 13px Manrope,sans-serif;display:block;line-height:1.1}.resource small{font-size:7px;color:#91a5a2;letter-spacing:1.1px;display:block;margin-top:3px}.bottom-hud{position:absolute;bottom:19px;left:25px;right:25px;display:flex;justify-content:space-between;align-items:end;z-index:3}.left-hud,.right-hud{display:flex;align-items:center;gap:10px}.map-btn,.journal-btn{height:36px;border-radius:10px;padding:0 13px;font-size:8px;letter-spacing:1.2px;font-weight:700;color:#e0e9df}.map-btn span{font-size:15px;color:#bddfca;margin-right:6px;vertical-align:-1px}.control-tip{font-size:8px;letter-spacing:1px;color:#d5e0d8;text-shadow:0 1px 5px #172b31}.control-tip kbd{font:700 8px 'DM Sans',sans-serif;color:#f1d29a;background:rgba(24,40,44,.68);border:1px solid rgba(255,255,255,.18);padding:4px 5px;border-radius:4px;margin:0 4px 0 10px}.build-label{font-size:8px;letter-spacing:1.2px;color:#f5d894;display:none}.build-label.active{display:inline}.build-btn{height:42px;padding:0 17px;border:0;border-radius:11px;background:#d7ba88;color:#332c21;font-weight:800;font-size:9px;letter-spacing:1.4px;box-shadow:0 5px 16px #13273144}.build-btn span{font-size:17px;vertical-align:-2px;margin-right:4px}.journal-btn{height:38px}.footer{display:flex;align-items:center;justify-content:space-between;padding:0 32px;color:#738589;font-size:8px;letter-spacing:1.5px;background:#101a27}.toast{position:absolute;top:47%;left:50%;transform:translate(-50%,10px);opacity:0;z-index:8;padding:11px 16px;background:rgba(18,34,42,.92);border:1px solid rgba(217,235,219,.21);border-radius:10px;color:#e9e9dc;font-size:12px;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction-hint{position:absolute;left:50%;bottom:94px;transform:translateX(-50%);padding:8px 12px;background:rgba(18,34,42,.77);border:1px solid rgba(255,255,255,.16);border-radius:9px;color:#eff1e8;font-size:10px;display:none;pointer-events:none}.interaction-hint.visible{display:block}.interaction-hint kbd{color:#e6cc98;margin-right:6px}.build-panel,.journal-panel{position:fixed;z-index:10;right:0;top:68px;bottom:30px;width:365px;background:rgba(17,31,40,.97);border-left:1px solid var(--line);padding:27px 25px;transform:translateX(105%);transition:transform .28s ease;overflow:auto;box-shadow:-25px 0 70px rgba(9,18,24,.25)}.build-panel.open,.journal-panel.open{transform:translateX(0)}.panel-head{display:flex;justify-content:space-between;align-items:flex-start}.panel-head small{color:#b6d5c1;font-size:8px;letter-spacing:1.6px;font-weight:700}.panel-head h2{font:700 23px Manrope,sans-serif;margin:7px 0 0;letter-spacing:-.7px}.close-btn{border:1px solid var(--line);background:#20323a;border-radius:8px;width:31px;height:31px;font-size:21px;color:#c9d4cd;line-height:1}.panel-note{font-size:11px;color:#9eafad;line-height:1.55;margin:15px 0 20px}.blueprint-list,.skin-list{display:grid;gap:9px}.blueprint-card,.skin-card{width:100%;text-align:left;display:flex;align-items:center;gap:13px;padding:12px;border:1px solid rgba(218,236,224,.13);background:#1b2c35;border-radius:11px;transition:.2s}.blueprint-card:hover,.blueprint-card.selected,.skin-card:hover{border-color:#b9d3bb;background:#22383c}.blueprint-art{width:49px;height:49px;border-radius:9px;background:linear-gradient(140deg,#385c56,#273b3e);display:grid;place-items:center;font-size:24px;flex-shrink:0}.blueprint-copy{flex:1}.blueprint-copy b,.skin-copy b{font:700 12px Manrope,sans-serif;display:block}.blueprint-copy small,.skin-copy small{display:block;margin-top:4px;font-size:9px;color:#9aadaa}.cost{display:flex;gap:6px;margin-top:7px;color:#b9c9c1;font-size:9px}.cost em{font-style:normal}.blueprint-card .choose{font-size:8px;color:#d6bd8b;letter-spacing:1px}.panel-tip{position:absolute;bottom:24px;left:25px;right:25px;border-top:1px solid var(--line);padding-top:14px;font-size:9px;color:#819391;line-height:1.55}.skin-card{padding:10px}.skin-art{width:47px;height:53px;border-radius:8px;display:grid;place-items:center;font-size:24px;background:linear-gradient(#38566a,#263844)}.skin-card:nth-child(2) .skin-art{background:linear-gradient(#985e54,#493c44)}.skin-card:nth-child(3) .skin-art{background:linear-gradient(#a99054,#5b4b37)}.skin-copy{flex:1}.skin-card button{background:#d7ba88;border:0;color:#332c21;font-weight:800;font-size:8px;letter-spacing:.7px;padding:8px;border-radius:7px}.skin-card button:disabled{background:#34464a;color:#a9bab3}.journal-panel{width:400px}.journal-entry{border-left:1px solid #6d947e;padding:0 0 21px 16px;margin:20px 0 0;color:#a9b8b2;font-size:11px;line-height:1.6}.journal-entry b{display:block;color:#edf0e7;font:700 12px Manrope,sans-serif;margin-bottom:4px}.journal-entry .entry-time{font-size:8px;letter-spacing:1px;color:#bad7bf}.modal-backdrop{position:fixed;inset:0;z-index:20;background:rgba(5,13,18,.62);display:grid;place-items:center;padding:20px}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(410px,100%);padding:36px 36px 30px;border-radius:18px;text-align:center;background:rgba(24,42,49,.97)}.modal-close{position:absolute;right:15px;top:15px}.modal-symbol{font-size:30px;color:var(--gold);margin-bottom:13px}.modal>small{font-size:8px;letter-spacing:1.8px;color:#bad5c1;font-weight:700}.modal h2{font:700 23px Manrope,sans-serif;margin:10px 0}.modal p{color:#b2c0ba;font-size:12px;line-height:1.7;margin:0 auto 23px;max-width:310px}.primary-btn{border:0;border-radius:9px;background:#d7ba88;color:#332c21;padding:12px 18px;font-size:9px;letter-spacing:1.3px;font-weight:800}.primary-btn span{margin-left:18px}.mobile-controls{display:none}
@media(max-width:800px){body{overflow:hidden}.game-shell{grid-template-rows:58px 1fr 24px;min-height:0}.topbar{padding:0 15px}.brand{font-size:11px}.brand-mark{height:31px;width:31px}.top-center{display:none}.top-actions{gap:6px}.icon-btn{width:31px;height:31px}.game-area{min-height:0}.quest-card{top:12px;left:12px;width:min(270px,calc(100% - 24px));padding:12px 14px}.quest-card h1{font-size:16px;margin:8px 0 4px}.quest-card p{font-size:10px;margin-bottom:10px}.quest-foot{margin-top:7px}.weather-pill{top:auto;bottom:90px;left:12px;right:auto;height:30px;font-size:7px;padding:0 10px}.resource-tray{top:13px;right:12px;gap:7px;padding:8px}.resource{gap:5px;min-width:38px}.resource-tray>i{height:20px}.resource-icon{font-size:12px}.resource b{font-size:11px}.resource small{font-size:6px}.bottom-hud{left:10px;right:10px;bottom:11px;align-items:end}.left-hud{gap:0}.map-btn{height:35px;padding:0 9px;font-size:7px}.control-tip{display:none}.right-hud{gap:7px}.build-btn{height:38px;padding:0 11px;font-size:8px}.journal-btn{height:35px;padding:0 10px;font-size:13px}.journal-btn span{display:none}.build-label{display:none!important}.footer{padding:0 14px;font-size:7px}.build-panel,.journal-panel{top:58px;bottom:24px;width:min(360px,100%);padding:22px 18px}.panel-tip{left:18px;right:18px;bottom:14px}.mobile-controls{display:flex;position:absolute;left:14px;bottom:61px;right:14px;align-items:end;justify-content:space-between;pointer-events:none}.dpad{pointer-events:auto;display:grid;gap:2px}.dpad>button,.dpad div button{width:37px;height:34px;border:1px solid rgba(239,244,224,.2);border-radius:8px;background:rgba(19,35,43,.62);backdrop-filter:blur(6px);color:#e8e9de;font-size:11px}.dpad>button{margin:auto;display:block}.dpad div{display:flex;gap:2px}.mobile-action{pointer-events:auto;border:1px solid rgba(239,244,224,.24);background:rgba(19,35,43,.8);border-radius:10px;color:#e3c88e;font-size:9px;letter-spacing:1px;font-weight:800;padding:12px 16px;margin-bottom:2px}.interaction-hint{bottom:141px;font-size:9px}.modal{padding:31px 24px 24px}.game-area canvas{touch-action:none}}
@media(max-width:430px){.quest-card{width:calc(100% - 24px);top:10px}.quest-card p{max-width:220px}.weather-pill{bottom:86px}.resource-tray{top:94px;right:12px}.bottom-hud{bottom:8px}.mobile-controls{bottom:56px}.footer span:last-child{display:none}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const COLS = 17, ROWS = 14, TW = 58, TH = 30;
  const $ = id => document.getElementById(id);
  const blueprints = [
    {id:'beacon',name:'Wind beacon',icon:'◈',desc:'A lantern to guide lost travelers.',cost:{wood:3,stone:2,essence:1}},
    {id:'cottage',name:'Cloud cottage',icon:'⌂',desc:'A cozy place to rest and dream.',cost:{wood:4,stone:1}},
    {id:'garden',name:'Sky garden',icon:'❀',desc:'A bright patch for island flowers.',cost:{wood:2,stone:1}},
    {id:'windmill',name:'Petal windmill',icon:'✣',desc:'Catch the breeze and make it sing.',cost:{wood:3,stone:2}}
  ];
  const skins = [
    {id:'wanderer',name:'Island wanderer',icon:'◉',cost:0},
    {id:'saffron',name:'Saffron festival',icon:'✺',cost:60},
    {id:'royal',name:'Royal skyguard',icon:'♜',cost:140}
  ];
  const nodeSeeds = [
    ['wood',3,4],['wood',5,9],['wood',7,3],['wood',11,4],['wood',13,8],['wood',4,11],['wood',10,11],['wood',14,5],
    ['stone',2,7],['stone',6,6],['stone',12,6],['stone',14,10],['stone',8,11],['stone',3,9],['stone',11,2],
    ['essence',7,2],['essence',12,9],['essence',5,4],['essence',9,10]
  ];
  const base = {
    player:{x:8,y:7}, resources:{wood:0,stone:0,essence:0}, stars:30, stage:0,
    nodes:nodeSeeds.map(([type,x,y],i)=>({id:i,type,x,y,gathered:false})),
    buildings:[], skin:'wanderer', owned:['wanderer'], day:1, journal:[], glider:false
  };
  let state = loadState(), keys = new Set(), touchDirs = new Set(), lastTime = 0, toastTimer, selected = null, buildMode = false, soundOn = false;
  let view = {scale:1, cx:0, cy:0, width:0, height:0}, nearby = null, showMap = false;
  const land = (x,y) => {
    if(x<0||y<0||x>=COLS||y>=ROWS) return false;
    const nx=(x-8)/8.5, ny=(y-6.5)/7;
    const r=nx*nx+ny*ny;
    const waviness=.09*Math.sin(x*1.6+y*.8)+.06*Math.cos(y*2.2-x*.65);
    return r < 1.03 + waviness && !(x<3&&y<3) && !(x>14&&y<3) && !(x<2&&y>10);
  };
  function loadState(){
    try {const saved=JSON.parse(localStorage.getItem('cloudhaven-save')); if(saved&&saved.player&&Array.isArray(saved.nodes)) return {...structuredClone(base),...saved,resources:{...base.resources,...saved.resources}};}catch(e){}
    return structuredClone(base);
  }
  function save(){try{localStorage.setItem('cloudhaven-save',JSON.stringify(state));}catch(e){}}
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  function setJournal(title,text){state.journal.unshift({title,text,time:`DAY ${String(state.day).padStart(2,'0')}`});state.journal=state.journal.slice(0,8);save()}
  function openModal(title,copy,eyebrow='A NOTE FROM THE WIND'){$('modal-title').textContent=title;$('modal-copy').textContent=copy;$('modal-eyebrow').textContent=eyebrow;$('modal-backdrop').hidden=false}
  function closeModal(){$('modal-backdrop').hidden=true}
  function drawSky(t){
    const g=ctx.createLinearGradient(0,0,0,view.height);g.addColorStop(0,'#83bdc1');g.addColorStop(.52,'#b5d5c9');g.addColorStop(1,'#e0d9b8');ctx.fillStyle=g;ctx.fillRect(0,0,view.width,view.height);
    const sun=ctx.createRadialGradient(view.width*.79,view.height*.2,3,view.width*.79,view.height*.2,130);sun.addColorStop(0,'rgba(255,244,198,.48)');sun.addColorStop(1,'rgba(255,244,198,0)');ctx.fillStyle=sun;ctx.fillRect(0,0,view.width,view.height);
    for(let i=0;i<9;i++){let x=((i*197+(t*.004*(i%2?1:-1))+view.width*1.4)%(view.width+220))-110;let y=80+(i*83%Math.max(150,view.height*.62));drawCloud(x,y,.6+(i%3)*.14,.12+(i%4)*.025)}
    // far islands floating in the haze
    for(let i=0;i<3;i++){const x=view.width*(.13+i*.38),y=view.height*(.26+(i%2)*.1);ctx.fillStyle='rgba(77,130,133,.18)';ctx.beginPath();ctx.ellipse(x,y,62+i*13,12+i*2,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(x-45,y);ctx.lineTo(x-25,y+27);ctx.lineTo(x+25,y+27);ctx.lineTo(x+49,y);ctx.fill()}
  }
  function drawCloud(x,y,s,a){ctx.save();ctx.globalAlpha=a;ctx.fillStyle='#f4f3df';ctx.beginPath();ctx.ellipse(x,y,45*s,12*s,0,0,Math.PI*2);ctx.ellipse(x-17*s,y-7*s,20*s,13*s,0,0,Math.PI*2);ctx.ellipse(x+9*s,y-10*s,25*s,17*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}
  function iso(x,y,z=0){return {x:(x-y)*TW/2,y:(x+y)*TH/2-z}}
  function tileCenter(x,y,z=0){const p=iso(x,y,z);return {x:view.cx+p.x*view.scale,y:view.cy+p.y*view.scale}}
  function diamond(x,y,fill,stroke){ctx.beginPath();ctx.moveTo(x,y-TH/2);ctx.lineTo(x+TW/2,y);ctx.lineTo(x,y+TH/2);ctx.lineTo(x-TW/2,y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function renderIsland(t){
    const pts=[];for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(land(x,y))pts.push({x,y});
    // soft island shadow and rocky underside
    ctx.save();ctx.globalAlpha=.22;ctx.fillStyle='#224f58';ctx.beginPath();ctx.ellipse(view.cx,view.cy+view.scale*205,view.scale*340,view.scale*58,0,0,Math.PI*2);ctx.fill();ctx.restore();
    // hanging rock silhouette
    const corners=[[-.8,0],[0,-.8],[.8,0],[0,.8]];ctx.beginPath();corners.forEach(([x,y],i)=>{const xx=view.cx+x*view.scale*510, yy=view.cy+view.scale*60+y*view.scale*230+(y>0?view.scale*110:0);i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)});ctx.closePath();const rock=ctx.createLinearGradient(0,view.cy,0,view.cy+view.scale*300);rock.addColorStop(0,'#796d58');rock.addColorStop(.35,'#655d51');rock.addColorStop(1,'#36464a');ctx.fillStyle=rock;ctx.fill();
    pts.sort((a,b)=>(a.x+a.y)-(b.x+b.y));
    for(const p of pts){const c=tileCenter(p.x,p.y);const edge= !land(p.x,p.y+1);if(edge){ctx.save();ctx.globalAlpha=.22;diamond(c.x,c.y+4*view.scale,'#334d49');ctx.restore()}
      let color=((p.x*3+p.y*7)%7===0)?'#82aa83':((p.x+p.y)%5===0?'#8fb58b':'#88af86');if((p.x+p.y)%11===0)color='#94b78d';diamond(c.x,c.y,color,'rgba(47,83,66,.13)');
      if((p.x*13+p.y*7)%31===2 && !occupied(p.x,p.y)){ctx.fillStyle='rgba(248,226,161,.65)';ctx.beginPath();ctx.arc(c.x-6*view.scale,c.y-2*view.scale,1.3*view.scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(237,185,180,.7)';ctx.beginPath();ctx.arc(c.x+7*view.scale,c.y+4*view.scale,1.2*view.scale,0,Math.PI*2);ctx.fill()}
    }
    // winding stone trail
    const trail=[[7,7],[7,8],[8,8],[9,8],[9,7],[9,6],[8,6]];for(const [x,y] of trail){const c=tileCenter(x,y);diamond(c.x,c.y-1*view.scale,'#b6ad91','rgba(84,84,66,.2)');ctx.beginPath();ctx.ellipse(c.x,c.y-2*view.scale,9*view.scale,4*view.scale,-.3,0,Math.PI*2);ctx.fillStyle='#c9bea0';ctx.fill()}
    // island home hearth
    drawBuilding({id:'home',type:'home',x:8,y:7});
    const drawables=[];for(const n of state.nodes)if(!n.gathered)drawables.push({kind:'node',item:n,depth:n.x+n.y});for(const b of state.buildings)drawables.push({kind:'building',item:b,depth:b.x+b.y});drawables.push({kind:'player',depth:state.player.x+state.player.y});drawables.sort((a,b)=>a.depth-b.depth);
    for(const d of drawables){if(d.kind==='node')drawNode(d.item,t);else if(d.kind==='building')drawBuilding(d.item);else drawPlayer(t)}
    if(buildMode&&selected){for(const p of pts){if(canBuildAt(p.x,p.y)){const c=tileCenter(p.x,p.y);ctx.save();ctx.globalAlpha=.58;diamond(c.x,c.y,'rgba(221,235,188,.42)','#e9d8a1');ctx.restore()}}}
    if(showMap)drawMapInset();
  }
  function occupied(x,y){return state.nodes.some(n=>!n.gathered&&n.x===x&&n.y===y)||state.buildings.some(b=>b.x===x&&b.y===y)||(x===8&&y===7)}
  function drawNode(n,t){const c=tileCenter(n.x,n.y);ctx.save();ctx.translate(c.x,c.y);ctx.scale(view.scale,view.scale);const sway=Math.sin(t*.002+n.id)*1.5;
    if(n.type==='wood'){
